import{H as e,V as t,et as n,j as r}from"./chunks/framework.C_EfTa_6.js";var i=JSON.parse(`{"title":"经典范式","description":"","frontmatter":{"title":"经典范式","order":0},"headers":[],"relativePath":"design/typical/index.md","filePath":"design/typical/index.md"}`),a={name:`design/typical/index.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="设计原则" tabindex="-1">设计原则 <a class="header-anchor" href="#设计原则" aria-label="Permalink to “设计原则”">​</a></h1><p>在软件工程多年的历史发展中，人们积累了丰富的软件设计经验。其中一些经验成为指导后来者的<strong>金科玉律</strong>，但是，时代在发展，过去的经验需要随着时代的变迁进行革新。</p><p>从需求到维护，设计原则贯穿软件生命周期的每个阶段：</p><ul><li><a href="./requirements">需求分析</a>——基础需求保底、刚需成交、亮点需求溢价，需求分层决定设计投入的优先级</li><li><a href="./macro">宏观指导</a>——康威定律等宏观规律，架构设计与组织结构的关系</li><li><a href="./ability">质量属性</a>——软件质量属性的全景框架（-ilities），各属性的定义与权衡</li><li><a href="./maintainability">可读性与可维护性</a>——可读不等于可维护，过度抽象是两者的典型冲突</li><li><a href="./reliability">可靠性与可用性</a>——可靠不能错，可用可以错但必须马上纠正</li><li><a href="./duty">职责分配</a>——迪米特法则、TDA、GRASP，谁该负责做什么</li><li><a href="./simplify">简化原则</a>——KISS、DRY、YAGNI，避免过度设计</li><li><a href="./refactor">重构</a>——不改变外部行为的前提下改进内部结构</li><li><a href="./swift">敏捷开发</a>——不追求第一天完美，追求十年内可修改</li><li><a href="./ddd">领域驱动设计</a>——业务领域知识到代码结构的映射</li></ul>`,4)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};